import assert from 'node:assert/strict';
import { randomBytes } from 'node:crypto';
import { writeFileSync } from 'node:fs';
if (!process.env.VOLTER_WORLD) throw new Error('Run this application through its World.');
assert.ok(process.env.TIKTOK_CLIENT_ID && process.env.TIKTOK_CLIENT_SECRET, 'the application receives its developer client credentials');
const api = 'https://open.tiktokapis.com';
const redirectUri = 'https://example.com/integrations/tiktok/callback';
const configured = await fetch(api + '/_twin/apps', {
  method: 'POST', headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ client_key: process.env.TIKTOK_CLIENT_ID, redirect_uris: [redirectUri] }),
});
assert.equal(configured.status, 200);
const app = await configured.json();
assert.equal(app.client_key, process.env.TIKTOK_CLIENT_ID, 'dashboard configuration selects the issued app');
assert.deepEqual(app.redirect_uris, [redirectUri]);
const username = 'observatory_' + randomBytes(5).toString('hex');
const displayName = 'Observatory community';
const password = randomBytes(32).toString('base64url');
const person = await fetch(api + '/_twin/people', {
  method: 'POST', headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ username, display_name: displayName, password }),
});
assert.equal(person.status, 201);
assert.equal((await person.json()).username, username);
const state = randomBytes(16).toString('hex');
const scope = 'user.info.basic,user.info.profile';
const authorizeUrl = new URL('https://www.tiktok.com/v2/auth/authorize/');
authorizeUrl.search = new URLSearchParams({ client_key: process.env.TIKTOK_CLIENT_ID, redirect_uri: redirectUri, response_type: 'code', scope, state }).toString();
function formFrom(html) {
  const action = /<form\b[^>]*action="([^"]+)"/.exec(html)?.[1];
  assert.ok(action, 'the hosted page offers its normal form');
  const body = new URLSearchParams();
  const decode = (value) => value.replaceAll('&quot;', '"').replaceAll('&lt;', '<').replaceAll('&gt;', '>').replaceAll('&amp;', '&');
  for (const [input] of html.matchAll(/<input\b[^>]*>/g)) {
    const name = /\bname="([^"]+)"/.exec(input)?.[1];
    if (name) body.set(name, decode(/\bvalue="([^"]*)"/.exec(input)?.[1] ?? ''));
  }
  const url = new URL(decode(action), authorizeUrl);
  assert.equal(url.origin, authorizeUrl.origin);
  return { url, body };
}
const loginPage = await fetch(authorizeUrl);
assert.equal(loginPage.status, 200);
const loginHtml = await loginPage.text();
assert.ok(loginHtml.includes('Log in to TikTok'));
const login = formFrom(loginHtml);
login.body.set('username', username);
login.body.set('password', password);
const consentPage = await fetch(login.url, { method: 'POST', body: login.body, redirect: 'manual' });
assert.equal(consentPage.status, 200);
const consentHtml = await consentPage.text();
assert.ok(consentHtml.includes('would like to access your TikTok account'));
const consent = formFrom(consentHtml);
consent.body.set('decision', 'authorize');
const authorized = await fetch(consent.url, { method: 'POST', body: consent.body, redirect: 'manual' });
assert.equal(authorized.status, 302);
const location = authorized.headers.get('location');
assert.ok(location, 'the hosted authorization returns to the application');
const callback = new URL(location);
assert.equal(callback.origin + callback.pathname, redirectUri);
assert.equal(callback.searchParams.get('state'), state);
assert.equal(callback.searchParams.get('scopes'), scope);
const code = callback.searchParams.get('code');
assert.ok(code);
const exchanged = await fetch(api + '/v2/oauth/token/', {
  method: 'POST',
  body: new URLSearchParams({ client_key: process.env.TIKTOK_CLIENT_ID, client_secret: process.env.TIKTOK_CLIENT_SECRET, grant_type: 'authorization_code', code, redirect_uri: redirectUri }),
});
assert.equal(exchanged.status, 200);
const token = await exchanged.json();
assert.ok(typeof token.access_token === 'string' && token.access_token.length > 0);
assert.equal(token.token_type, 'Bearer');
assert.equal(token.scope, scope);
assert.ok(token.expires_in > 0 && token.open_id);
writeFileSync('.tiktok-token.json', JSON.stringify({ accessToken: token.access_token, openId: token.open_id, username, displayName, clientId: process.env.TIKTOK_CLIENT_ID }) + '\n', { mode: 0o600 });
await import('./readback.mjs');

