import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
if (!process.env.VOLTER_WORLD) throw new Error('Run this application through its World.');
const saved = JSON.parse(readFileSync('.tiktok-token.json', 'utf8'));
assert.equal(process.env.TIKTOK_CLIENT_ID, saved.clientId, 'resume retains the developer app');
const query = new URLSearchParams({ fields: 'open_id,username,display_name' });
const response = await fetch('https://open.tiktokapis.com/v2/user/info/?' + query, { headers: { Authorization: `Bearer ${saved.accessToken}` } });
assert.equal(response.status, 200);
const result = await response.json();
assert.equal(result.error.code, 'ok');
assert.equal(result.data.user.open_id, saved.openId);
assert.equal(result.data.user.username, saved.username);
assert.equal(result.data.user.display_name, saved.displayName);
console.log(JSON.stringify({ openId: result.data.user.open_id, username: result.data.user.username, displayName: result.data.user.display_name, retainedGrant: true }));
